#include "scamptrie_dynamic.h"
#include <algorithm>

static ip6_t normalized(ip6_t p, uint8_t len) {
    if (len == 0) return {0,0};
    if (len < 64) { p.hi &= (~0ULL << (64-len)); p.lo=0; return p; }
    if (len == 64) { p.lo=0; return p; }
    p.lo &= (~0ULL << (128-len));
    return p;
}

uint32_t ScampTrieDynamic::insert_prefix(ip6_t p, uint8_t len, nexthop_t nh) {
    p = normalized(p,len);
    fib_[PrefixKey{p.hi,p.lo,len}] = nh; // unordered_map assignment is an upsert
    return SCAMPTRIE_OK;
}

nexthop_t ScampTrieDynamic::lookup(ip6_t p, uint32_t &bmp_idx, int) const {
    bmp_idx = 0;
    // Trying normalized keys from longest to shortest is both exact LPM and
    // independent of insertion order.  There are only 8192 distinct keys in
    // a request, so the fixed 129 probes are inexpensive.
    for (int l=128; l>=0; --l) {
        ip6_t q = normalized(p, static_cast<uint8_t>(l));
        auto it=fib_.find(PrefixKey{q.hi,q.lo,static_cast<uint8_t>(l)});
        if (it!=fib_.end()) return it->second;
    }
    return LPM_INVALID_NH;
}

const std::vector<LivePrefix> ScampTrieDynamic::prefixes() const {
    std::vector<LivePrefix> out;
    out.reserve(fib_.size());
    for (const auto& x:fib_) out.push_back(LivePrefix{{x.first.hi,x.first.lo},x.first.len,x.second});
    std::sort(out.begin(),out.end(),[](const LivePrefix&a,const LivePrefix&b){
        if (a.len!=b.len) return a.len<b.len;
        if (a.ip.hi!=b.ip.hi) return a.ip.hi<b.ip.hi;
        return a.ip.lo<b.ip.lo;
    });
    return out;
}
